<script>
const $=s=>document.querySelector(s),rp=n=>(n<0?'-':'')+'Rp'+Math.abs(n).toLocaleString('id-ID'),jt=n=>'Rp'+(n/1e6).toLocaleString('id-ID',{maximumFractionDigits:1})+' jt';
